// BrentAdminServiceHandler is an implementation of the brent.BrentAdminService service.
type BrentAdminServiceHandler interface {
	// Executes a workflow from a natural-language prompt. The server streams
	// steps as the agent reasons, calls MCP tools, and produces a final result.
	// The stream ends with either a CompletionStep or a terminal ErrorStep.
	// Operator-only; gated on admin:write.
	ExecuteWorkflow(context.Context, *connect.Request[sdp_go.ExecuteWorkflowRequest], *connect.ServerStream[sdp_go.ExecuteWorkflowResponse]) error
	// Lists all tracked runs (both UI-initiated and webhook-triggered).
	// Operator-only; gated on admin:read.
	ListRuns(context.Context, *connect.Request[sdp_go.ListRunsRequest]) (*connect.Response[sdp_go.ListRunsResponse], error)
	// Streams steps for a specific run. Replays buffered steps first, then
	// streams live steps until the run completes or the client disconnects.
	// Operator-only; gated on admin:read.
	WatchRun(context.Context, *connect.Request[sdp_go.WatchRunRequest], *connect.ServerStream[sdp_go.ExecuteWorkflowResponse]) error
	// Streams live capital-E Events for the caller's account. No history or
	// replay: clients only receive events emitted after the stream starts.
	// Operator-only; gated on admin:read.
	StreamEvents(context.Context, *connect.Request[sdp_go.StreamEventsRequest], *connect.ServerStream[sdp_go.StreamEventsResponse]) error
	// Lists persisted capital-E Events for one account, newest first. Operator
	// inspection of the raw audit trail; gated on admin:read. account_name is
	// REQUIRED (no caller-account fallback) — operators choose the tenant to
	// inspect. Keyset-paginated via after_cursor / next_cursor. The read writes
	// nothing (no meta-audit event is emitted).
	ListEvents(context.Context, *connect.Request[sdp_go.ListEventsRequest]) (*connect.Response[sdp_go.ListEventsResponse], error)
	// Cancels a running workflow. Idempotent for already-completed runs.
	// Operator-only; gated on admin:write.
	CancelRun(context.Context, *connect.Request[sdp_go.CancelRunRequest]) (*connect.Response[sdp_go.CancelRunResponse], error)
	// Sends a follow-up question against a completed run's OpenAI context.
	// The server streams the model's answer as ExecuteWorkflowResponse steps.
	// Returns NotFound when the run has no stored response ID.
	// Operator-only; gated on admin:write.
	SendQuestion(context.Context, *connect.Request[sdp_go.SendQuestionRequest], *connect.ServerStream[sdp_go.ExecuteWorkflowResponse]) error
	// Lists every non-deleted plan across every tenant. Operator-only; gated
	// on admin:read (brent-area51 and staff Admin role).
	//
	// Summary fields only — `content` is omitted to keep payloads bounded.
	// Use GetPlan to fetch the full plan body.
	ListPlans(context.Context, *connect.Request[sdp_go.AdminListPlansRequest]) (*connect.Response[sdp_go.AdminListPlansResponse], error)
	// Fetches a single plan by ID, ignoring account scope. Returns the full
	// plan (including `content`) plus a summary of every related review on
	// the same plan. Same admin:read gate as ListPlans. Returns NotFound for
	// unknown / soft-deleted plans.
	GetPlan(context.Context, *connect.Request[sdp_go.AdminGetPlanRequest]) (*connect.Response[sdp_go.AdminGetPlanResponse], error)
	// Lists every non-deleted review across every tenant. Same admin:read
	// gate as ListPlans.
	ListReviews(context.Context, *connect.Request[sdp_go.AdminListReviewsRequest]) (*connect.Response[sdp_go.AdminListReviewsResponse], error)
	// Fetches a single review by ID, ignoring account scope. Returns the
	// review plus a summary of its parent plan (nil when the parent has been
	// hard-deleted, which shouldn't happen today but keeps orphaned reviews
	// debuggable). Same admin:read gate as ListPlans. Returns NotFound for
	// unknown / soft-deleted reviews.
	GetReview(context.Context, *connect.Request[sdp_go.AdminGetReviewRequest]) (*connect.Response[sdp_go.AdminGetReviewResponse], error)
	// Lists every known tenant as AccountSummary rows. Cross-tenant operator
	// endpoint gated on admin:read (not the standard brent:read). Only staff
	// with the platform Admin role hold this scope; brent-area51 requests it at login.
	ListAccounts(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[sdp_go.AdminListAccountsResponse], error)
	// Returns a rich activity summary for a single account: integration status,
	// plan / review / workflow-run / pull-request counts, workflow-run error
	// count, deviation verdict distribution, last-active timestamp, and the
	// handful of most recent runs. Cross-tenant operator endpoint gated on
	// admin:read. An unknown account returns an empty (zero-valued) summary
	// rather than NotFound, so the detail page renders cleanly for a tenant
	// with no activity yet.
	GetAccountSummary(context.Context, *connect.Request[sdp_go.AdminGetAccountSummaryRequest]) (*connect.Response[sdp_go.AdminGetAccountSummaryResponse], error)
	// Runs a fixed set of health heuristics over a single account's recent
	// activity and returns plain-language findings, each with a severity. This
	// is an internal-only operator coaching aid — the findings are NEVER shown
	// to the customer. Computed live on each call from database aggregates; no
	// storage and no background job. Cross-tenant operator endpoint gated on
	// admin:read.
	GetAccountHealthAnalysis(context.Context, *connect.Request[sdp_go.AdminGetAccountHealthAnalysisRequest]) (*connect.Response[sdp_go.AdminGetAccountHealthAnalysisResponse], error)
	// Lists GitHub repositories available to the account through its installed
	// GitHub App. Cross-tenant operator endpoint gated on admin:read.
	ListAccountMetricRepos(context.Context, *connect.Request[sdp_go.AdminListAccountMetricReposRequest]) (*connect.Response[sdp_go.AdminListAccountMetricReposResponse], error)
	// Starts a temporary in-process metrics comparison run for one account/repo.
	// The report body is not persisted; callers poll GetAccountMetricsComparisonRun.
	// Cross-tenant operator endpoint gated on admin:write.
	StartAccountMetricsComparison(context.Context, *connect.Request[sdp_go.AdminStartAccountMetricsComparisonRequest]) (*connect.Response[sdp_go.AdminStartAccountMetricsComparisonResponse], error)
	// Polls a temporary metrics comparison run. Cross-tenant operator endpoint
	// gated on admin:read. Completed runs include sandbox-renderable HTML.
	GetAccountMetricsComparisonRun(context.Context, *connect.Request[sdp_go.AdminGetAccountMetricsComparisonRunRequest]) (*connect.Response[sdp_go.AdminGetAccountMetricsComparisonRunResponse], error)
	// Reads the Brent deviation settings (red_finding_kinds) for any account.
	// This is the operator-facing twin of GetBrentSettings: it gates on
	// admin:read and requires an explicit account_name, so the brent-area51
	// account detail page can show a customer's settings without holding that
	// customer's brent:read scope. account_name is required (no caller-account
	// fallback).
	GetAccountBrentSettings(context.Context, *connect.Request[sdp_go.AdminGetAccountBrentSettingsRequest]) (*connect.Response[sdp_go.GetBrentSettingsResponse], error)
	// Updates the Brent deviation settings (red_finding_kinds) for any account.
	// Operator-facing twin of UpdateBrentSettings: gates on admin:write and
	// requires an explicit account_name. PATCH semantics — omit red_finding_kinds
	// to leave it unchanged; pass an empty array to disable red on all kinds.
	UpdateAccountBrentSettings(context.Context, *connect.Request[sdp_go.AdminUpdateAccountBrentSettingsRequest]) (*connect.Response[sdp_go.UpdateBrentSettingsResponse], error)
	// Reads an account's LLM provider key status for support triage. Operator-facing
	// twin of GetWorkspaceLLMCredentialStatus: gates on admin:read and takes an
	// explicit account_name, so brent-area51 can show any account's key status
	// without holding that account's brent:read scope. Metadata only — never the
	// secret. account_name is required (no caller-account fallback).
	GetAccountLLMCredentialStatus(context.Context, *connect.Request[sdp_go.AdminGetAccountLLMCredentialStatusRequest]) (*connect.Response[sdp_go.AdminGetAccountLLMCredentialStatusResponse], error)
	// Lists organisation_app_installations for one account with credential-presence
	// flags, shared readiness fields, and workspace integration roles.
	// Metadata only — never secrets. Cross-tenant; gated on admin:read.
	// account_name required.
	ListAccountIntegrations(context.Context, *connect.Request[sdp_go.AdminListAccountIntegrationsRequest]) (*connect.Response[sdp_go.AdminListAccountIntegrationsResponse], error)
	// Lists workflow definitions for the caller's account, ordered by name.
	// Account-scoped: callers see only their own tenant's rows. Operator-only;
	// gated on admin:read. Returns summary fields only (no body_template, no on_yaml);
	// use GetWorkflow for the full definition.
	ListWorkflows(context.Context, *connect.Request[sdp_go.ListWorkflowsRequest]) (*connect.Response[sdp_go.ListWorkflowsResponse], error)
	// Fetches a single workflow definition by ID within the caller's account.
	// Returns NotFound when the workflow is missing, soft-deleted, or owned by
	// a different account. Same admin:read gate as ListWorkflows.
	GetWorkflow(context.Context, *connect.Request[sdp_go.GetWorkflowRequest]) (*connect.Response[sdp_go.GetWorkflowResponse], error)
	// Lists workflow runs for the caller's account, newest first. Account-
	// scoped; gated on admin:read. Supports cursor pagination (limit +
	// after_cursor) and an optional workflow_name filter for the per-workflow
	// run-list view.
	ListWorkflowRuns(context.Context, *connect.Request[sdp_go.ListWorkflowRunsRequest]) (*connect.Response[sdp_go.ListWorkflowRunsResponse], error)
	// Fetches a single workflow run by ID within the caller's account. Returns
	// the full WorkflowRun (including prompt and the typed Event payload that
	// triggered it) plus an optional parent WorkflowSummary lookable up by
	// (account_name, name). Same admin:read gate.
	GetWorkflowRun(context.Context, *connect.Request[sdp_go.GetWorkflowRunRequest]) (*connect.Response[sdp_go.GetWorkflowRunResponse], error)
	// Returns persisted steps for ancestor runs in the resumed_from_run_id chain
	// (oldest first). The current run's live tail stays on WatchRun. Same
	// admin:read gate as GetWorkflowRun.
	GetWorkflowRunThreadHistory(context.Context, *connect.Request[sdp_go.GetWorkflowRunThreadHistoryRequest]) (*connect.Response[sdp_go.GetWorkflowRunThreadHistoryResponse], error)
	// Lists pull requests for the caller's tenant, sorted by updated_at DESC.
	// Account-scoped: callers see only their own rows. Operator-only; gated on admin:read.
	// The `state` filter accepts "" (default → open), "open", "closed"
	// (state='closed' AND merged=false), "merged" (state='closed' AND
	// merged=true), or "all". Returns summary fields including linked-plan info
	// and the latest deviation verdict for the PR's current head SHA.
	ListPullRequests(context.Context, *connect.Request[sdp_go.ListPullRequestsRequest]) (*connect.Response[sdp_go.ListPullRequestsResponse], error)
	// Fetches a single pull request by its UUID. Account-scoped: a pr_id from
	// another tenant returns NotFound (existence is never surfaced). Gated on
	// admin:read.
	GetPullRequestByID(context.Context, *connect.Request[sdp_go.GetPullRequestByIDRequest]) (*connect.Response[sdp_go.GetPullRequestByIDResponse], error)
	// Lists deviation analyses for a pull request, newest-first by started_at.
	// Account-scoped: a pr_id from another tenant returns an empty list (not an
	// error). Gated on admin:read.
	ListDeviationAnalysesForPR(context.Context, *connect.Request[sdp_go.ListDeviationAnalysesForPRRequest]) (*connect.Response[sdp_go.ListDeviationAnalysesForPRResponse], error)
	// Lists principals across every tenant for the Area51 debug UI. Operator-only;
	// gated on admin:read. Summary fields only; use GetPrincipal for
	// identities and bindings.
	ListPrincipals(context.Context, *connect.Request[sdp_go.AdminListPrincipalsRequest]) (*connect.Response[sdp_go.AdminListPrincipalsResponse], error)
	// Fetches a single principal by UUID, ignoring account scope, plus every
	// identity and binding row (including tombstoned bindings). Same admin:read
	// gate as ListPrincipals. Returns NotFound for unknown principals.
	GetPrincipal(context.Context, *connect.Request[sdp_go.AdminGetPrincipalRequest]) (*connect.Response[sdp_go.AdminGetPrincipalResponse], error)
	// Upserts a verified binding on any principal in any tenant. Operator-only;
	// gated on admin:write.
	UpsertPrincipalBinding(context.Context, *connect.Request[sdp_go.AdminUpsertPrincipalBindingRequest]) (*connect.Response[sdp_go.AdminUpsertPrincipalBindingResponse], error)
	// Tombstones a verified binding row by its external_id. Operator-only;
	// gated on admin:write.
	DeletePrincipalBinding(context.Context, *connect.Request[sdp_go.AdminDeletePrincipalBindingRequest]) (*connect.Response[sdp_go.AdminDeletePrincipalBindingResponse], error)
	// Updates display_name and/or status on any principal. Operator-only;
	// gated on admin:write.
	UpdatePrincipal(context.Context, *connect.Request[sdp_go.AdminUpdatePrincipalRequest]) (*connect.Response[sdp_go.AdminUpdatePrincipalResponse], error)
	// Inserts an identity row on any principal. Operator-only; gated on admin:write.
	CreatePrincipalIdentity(context.Context, *connect.Request[sdp_go.AdminCreatePrincipalIdentityRequest]) (*connect.Response[sdp_go.AdminCreatePrincipalIdentityResponse], error)
	// Deletes an identity row by external_id. Operator-only; gated on admin:write.
	DeletePrincipalIdentity(context.Context, *connect.Request[sdp_go.AdminDeletePrincipalIdentityRequest]) (*connect.Response[sdp_go.AdminDeletePrincipalIdentityResponse], error)
	// Validates and stores a per-principal integration secret for a provider.
	// Write-only: the secret is never returned. Operator-only; gated on admin:write.
	SetPrincipalCredential(context.Context, *connect.Request[sdp_go.AdminSetPrincipalCredentialRequest]) (*connect.Response[sdp_go.AdminSetPrincipalCredentialResponse], error)
	// Lists credential connection presence across principals (metadata only).
	// Operator-only; gated on admin:read.
	ListPrincipalCredentialConnections(context.Context, *connect.Request[sdp_go.AdminListPrincipalCredentialConnectionsRequest]) (*connect.Response[sdp_go.AdminListPrincipalCredentialConnectionsResponse], error)
	// Clears a stored credential and tombstones the matching verified binding.
	// Operator-only; gated on admin:write.
	DeletePrincipalCredential(context.Context, *connect.Request[sdp_go.AdminDeletePrincipalCredentialRequest]) (*connect.Response[sdp_go.AdminDeletePrincipalCredentialResponse], error)
	// Returns a chronological timeline table for one PR: Brent-local rows plus
	// a live GitHub overlay composed at request time. Account-scoped: a pr_id
	// from another tenant returns NotFound. GitHub failures surface as warnings
	// while Brent-local rows are still returned. Gated on admin:read.
	GetPullRequestTimeline(context.Context, *connect.Request[sdp_go.GetPullRequestTimelineRequest]) (*connect.Response[sdp_go.GetPullRequestTimelineResponse], error)
}

